// Vehicle control sound effects. Clips live in public/sfx and are generated by
// scripts/generate-sfx.mjs. Web Audio is used so actions triggered later by the
// assistant can play after the first tap has unlocked audio on the page.
(() => {
  const SETTINGS_KEY = 'account:settings'; // shared with Profile → Preferences
  const VOLUME = 0.5;
  const CLIPS = ['lock', 'start', 'climate', 'trunk', 'charge']
    .flatMap((control) => [`${control}-off`, `${control}-on`]);
  const files = new Map();
  const decoded = new Map();
  const playing = new Map();
  let ctx = null;

  function enabled() {
    try {
      return JSON.parse(localStorage.getItem(SETTINGS_KEY) || '{}').sfx !== false;
    } catch {
      return true; // blocked storage should not silence the controls
    }
  }

  function ensureContext() {
    const Ctx = window.AudioContext || window.webkitAudioContext;
    if (!Ctx) return null;
    if (!ctx) ctx = new Ctx();
    if (ctx.state === 'suspended') ctx.resume().catch(() => {});
    return ctx;
  }

  function fetchClip(name) {
    if (!files.has(name)) {
      files.set(name, fetch(`sfx/${name}.mp3`)
        .then((res) => (res.ok ? res.arrayBuffer() : null))
        .catch(() => null));
    }
    return files.get(name);
  }

  function decode(name) {
    if (!decoded.has(name)) {
      decoded.set(name, fetchClip(name).then((data) => {
        if (!data) return null;
        const audio = ensureContext();
        return audio ? audio.decodeAudioData(data).catch(() => null) : null;
      }));
    }
    return decoded.get(name);
  }

  // Browsers only start audio after a gesture. The first tap also warms every
  // clip so assistant-triggered controls can play later without another tap.
  function unlock() {
    if (!ensureContext()) return;
    CLIPS.forEach(decode);
  }

  function play(control, on) {
    const name = `${control}-${on ? 'on' : 'off'}`;
    if (!CLIPS.includes(name) || !enabled()) return;
    const audio = ensureContext();
    if (!audio) return;

    decode(name).then((buffer) => {
      if (!buffer || !enabled()) return;
      const start = () => {
        try { playing.get(control)?.stop(); } catch { /* already ended */ }
        const source = audio.createBufferSource();
        const gain = audio.createGain();
        source.buffer = buffer;
        gain.gain.value = VOLUME;
        source.connect(gain).connect(audio.destination);
        source.onended = () => {
          if (playing.get(control) === source) playing.delete(control);
        };
        playing.set(control, source);
        source.start();
      };
      if (audio.state === 'suspended') audio.resume().then(start).catch(() => {});
      else start();
    });
  }

  window.addEventListener('pointerdown', unlock, { once: true });
  window.addEventListener('keydown', unlock, { once: true });
  window.SFX = { play };

  // Prefetch the small clips in the background; nothing plays until a control is used.
  const warm = () => CLIPS.forEach(fetchClip);
  if ('requestIdleCallback' in window) requestIdleCallback(warm);
  else setTimeout(warm, 1200);
})();
